import{_ as t,o,c as a,a4 as l}from"./chunks/framework.DzJZdBQK.js";const d=JSON.parse('{"title":"写作课作业-086","description":"","frontmatter":{"date":"2020-10-22T19:37:37","title":"写作课作业-086","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/086.md","filePath":"posts/homework/086.md"}'),p={name:"posts/homework/086.md"};function r(s,e,c,i,n,_){return o(),a("div",null,[...e[0]||(e[0]=[l('<blockquote><p>《微信互联网平民创业》之《18.有哪些事情是你必须做的?》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><blockquote><p>「读书」和赚钱绝对是两回事。</p></blockquote><blockquote><p>真正能变现的，并不是知识本身，而是「知识落差」。</p></blockquote><blockquote><p>与其乱读书，与其四处胡乱扑腾，与其假装干自己不爱干的事儿，还不如老老实实干一件事儿，尤其是平民，必须老老实实干这件事儿：锻炼。</p></blockquote><blockquote><p>健康是一切的根本。</p><p>没有健康，就没有办法干任何值得长期做的事情。</p><p>持续读书的人不见得更容易持续锻炼，但，反过来，持续锻炼的人更容易持续读书——事实上，持续锻炼的人更容易持续干任何事情！</p><p>健康的身体才是真正的门面。因为持续锻炼的结果是身材挺拔，身材挺拔是什么?是「你的人 格的铁证」—— 就这么简单直接粗暴有效!你不需要说什么，你一出现，你站在那里， 人们就能感受到......</p><p>身体健康直接影响心理健康;心理健康直接影响你的大脑对整个世界的理解 —— 绝大多 数人逃脱不了生理机能的约束和限制。</p><p>长期持续的锻炼，给我自己带来的最大收获，除了你可以想象到的那些之外，其实有一个很可能会让你非常意外：脾气越来越随和……</p></blockquote><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>健康是一切的根本，自己很早有意识到就是没有开始运动。家人提醒可以去跑步的时候，自己还是没有去运动，反而觉得烦。当因为自己身体开始有些异样开始游泳的时候，感叹自己的身体素质很差，当自己因为加入践行群，开始跑步的时候，发现其实也没有那么难。当看到这段文字的时候，其实自己应该做更多的锻炼。</p><p>有的时候，一件事情需要从不同的维度去讲解和感受，才有可能被接受，被理解，开始有所行动。</p><p>因为这样的原因，也认可榜样的力量，现在时不时的就带着儿子运动，比如，走健康步栈道，微信运动，游泳，在学校让儿子加入的也是足球兴趣小组。也时不时的会把这些运动当成一个比赛，让他赢，感受乐趣，让他输，接受挫败。当然更重要的是践行，健身和陪家人，在其中体会幸福。</p>',10)])])}const k=t(p,[["render",r]]);export{d as __pageData,k as default};
